'use strict';
const KEY='stay-together-v1';
const MODE_KEY=KEY+'-mode-v2',slotKey=mode=>KEY+'-isolated-'+mode;
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=s=>document.querySelector(s);
const labels={smart:'智能马桶',smartWash:'马桶清洗功能（臀洗／妇洗）',laundry:'免费自助洗衣',mold:'潮味／霉味反馈',opened:'开业年份',renovated:'翻新年份'};
const uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2);
const today=()=>new Date().toLocaleDateString('en-CA');
function demo(){
  const evidence=(id,text,claims,platform='小红书')=>({id,text,claims,platform,date:'2026-10-10',source:'',room:'与候选房型一致（演示设定）',confirmed:true,demo:true});
  return{version:1,mode:'demo',trip:{city:'杭州',checkin:'2026-11-13',checkout:'2026-11-16',area:'西湖周边，方便步行与地铁出行'},people:[
    {id:'me',name:'我',budget:800,budgetHard:true,requireSmart:true,requireLaundry:false,avoidMold:true,transitHard:false,maxMetro:15,weights:{price:2,transit:2,newness:5,facilities:5}},
    {id:'friend',name:'朋友',budget:650,budgetHard:true,requireSmart:false,requireLaundry:false,avoidMold:true,transitHard:false,maxMetro:10,weights:{price:5,transit:5,newness:2,facilities:2}}
  ],hotels:[
    {id:'h1',name:'栖屿 · 湖畔酒店',area:'西湖东岸 · 演示位置',room:'行政大床房 · 42㎡',price:718,metro:12,source:'',quoteDate:'2026-10-24',terms:'含双早 · 入住前一天可取消 · 含税（均为演示）',demo:true,facts:{opened:2024,renovated:null,smart:true,laundry:true,mold:false},evidence:[evidence('e1','行政大床房的卫浴做了干湿分离，有智能马桶。房间设备很新，去地铁站步行约12分钟。',{smart:true,opened:2024},'酒店资料'),evidence('e2','免费洗衣房很方便，洗烘一体。房间没有闻到潮味，安静，但价格比附近高一些。',{laundry:true,mold:false},'大众点评')]},
    {id:'h2',name:'木里 · 城市花园酒店',area:'湖滨商圈 · 演示位置',room:'花园大床房 · 32㎡',price:588,metro:5,source:'',quoteDate:'2026-10-24',terms:'含双早 · 入住前一天可取消 · 含税（均为演示）',demo:true,facts:{opened:2023,renovated:null,smart:true,laundry:true,mold:false},evidence:[evidence('e3','2023年开业，花园大床房配置智能马桶。地铁站步行约5分钟，楼下有便利店。',{smart:true,opened:2023},'酒店资料'),evidence('e4','住的房间干净，没闻到霉味。自助洗衣免费，但晚上洗衣可能要排队。房间比行政房紧凑。',{laundry:true,mold:false},'小红书')]},
    {id:'h3',name:'泊岸 · 新里酒店',area:'城市公园附近 · 演示位置',room:'景观大床房 · 38㎡',price:628,metro:9,source:'',quoteDate:'2026-10-24',terms:'含双早 · 入住前一天可取消 · 含税（均为演示）',demo:true,facts:{opened:2024,renovated:null,smart:true,laundry:true,mold:false},evidence:[evidence('e5','2024年新开的酒店，景观大床房的智能马桶和分区照明很实用。到地铁站需要走约9分钟。',{opened:2024,smart:true},'酒店资料'),evidence('e6','有免费洗衣房，客房没闻到潮味。房间动线舒适，不过洗衣房在另外一栋，需要走一小段。',{laundry:true,mold:false},'抖音')]},
    {id:'h4',name:'拾光 · 旧城客舍',area:'老城区 · 演示位置',room:'经典大床房 · 28㎡',price:428,metro:3,source:'',quoteDate:'2026-10-24',terms:'不含早餐 · 入住前一天可取消 · 含税（均为演示）',demo:true,facts:{opened:2018,renovated:2020,smart:false,laundry:null,mold:true},evidence:[evidence('e7','位置方便，房价便宜。住的经典房没有智能马桶，洗衣设施没有查到。',{smart:false},'酒店资料'),evidence('e8','房间设备有些年头了，雨天入住有一点潮味。交通确实方便。',{mold:true},'大众点评')]}
  ]};
}
let state;
const storageRecoveryErrors=new Map();
function readState(key){
 try{const raw=localStorage.getItem(key);if(raw===null||raw===''){storageRecoveryErrors.delete(key);return null;}const value=JSON.parse(raw);if(!validState(value)){storageRecoveryErrors.set(key,'saved_state_invalid');return null;}storageRecoveryErrors.delete(key);return value;}
 catch{storageRecoveryErrors.set(key,'saved_state_unreadable');return null;}
}
try{
 const legacy=readState(KEY),trip=readState(slotKey('trip')),exampleSlot=readState(slotKey('demo'));
 const mode=localStorage.getItem(MODE_KEY)==='demo'?'demo':'trip';
 // A non-empty unreadable slot is preserved byte-for-byte. Never initialize a
 // replacement or run the normal boot save while recovery is still required.
 if(!storageRecoveryErrors.size){
  if(!trip)localStorage.setItem(slotKey('trip'),JSON.stringify(HotelJourney.migrate(legacy,demo().people)));
  if(!exampleSlot){const example=demo();if(legacy){const oldDemo=legacy.hotels.filter(h=>h.demo);if(oldDemo.length)example.hotels=oldDemo;}localStorage.setItem(slotKey('demo'),JSON.stringify(example));}
 }
 state=(mode==='demo'?exampleSlot:trip)||(!storageRecoveryErrors.size?readState(slotKey(mode)):null)||HotelJourney.migrate(null,demo().people);state.mode=mode;
}catch{storageRecoveryErrors.set('startup','storage_read_failed');state=HotelJourney.migrate(null,demo().people);}
let view=(location.hash||'#compare').slice(1),filterHotel='',filterPlatform='',pendingImage=null,ocrBusy=false;
let objectURLs=[];
function validState(s){return s&&s.version===1&&s.trip&&typeof s.trip.city==='string'&&Array.isArray(s.people)&&s.people.length>0&&s.people.length<=8&&s.people.every(p=>p&&typeof p.id==='string'&&typeof p.name==='string'&&Number.isFinite(p.budget)&&p.budget>0&&p.weights&&['price','transit','newness','facilities'].every(k=>Number.isFinite(p.weights[k])&&p.weights[k]>=0&&p.weights[k]<=5))&&Array.isArray(s.hotels)&&s.hotels.length<=200&&new Set(s.hotels.map(h=>h?.id)).size===s.hotels.length&&s.hotels.every(h=>h&&typeof h.id==='string'&&typeof h.name==='string'&&h.facts&&Array.isArray(h.evidence)&&h.evidence.length<=200&&(h.price==null||Number.isFinite(h.price))&&(h.metro==null||Number.isFinite(h.metro)));}
function storageRecoveryHTML(){return storageRecoveryErrors.size?'<div class="notice storage-recovery-error" role="alert"><b>本机资料未能安全恢复，已暂停保存。</b><p>原储存内容未改动。当前页面可能不是原有行程，请勿把初始值当作已恢复资料；请先恢复有效资料后刷新页面，不要清除浏览器数据。</p></div>':'';}
function save(){if(storageRecoveryErrors.size){$('#storage-status').textContent='资料恢复异常 · 已暂停保存，原内容保留';return false;}if(!validState(state)){storageRecoveryErrors.set(slotKey(state.mode||'trip'),'current_state_invalid');$('#storage-status').textContent='当前资料未通过完整性检查 · 已暂停保存';toast('当前资料未通过完整性检查，已停止写入，原储存内容保留');return false;}try{localStorage.setItem(slotKey(state.mode||'trip'),JSON.stringify(state));localStorage.setItem(MODE_KEY,state.mode||'trip');$('#storage-status').textContent='已保存到当前浏览器';return true;}catch{$('#storage-status').textContent='保存失败，请导出备份';toast('浏览器储存空间不足，请先导出备份');return false;}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4200);}
function safeURL(s){try{const u=new URL(s);return ['http:','https:'].includes(u.protocol)?u.href:null;}catch{return null;}}
function link(s,text){const url=safeURL(s);return url?`<a class="quote-source" href="${E(url)}" target="_blank" rel="noopener noreferrer">${E(text||'打开来源 ↗')}</a>`:'<span class="evidence-meta">未提供原始链接</span>';}
const dbPromise=new Promise((resolve,reject)=>{const r=indexedDB.open('stay-together-images',1);r.onupgradeneeded=()=>r.result.createObjectStore('images');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});
dbPromise.catch(()=>{});
async function imagePut(id,data){const db=await dbPromise;await new Promise((resolve,reject)=>{const tx=db.transaction('images','readwrite');tx.objectStore('images').put(data,id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}
async function imageGet(id){try{const db=await dbPromise;return await new Promise((resolve,reject)=>{const r=db.transaction('images').objectStore('images').get(id);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}catch{return null;}}
async function imageDelete(id){try{const db=await dbPromise;db.transaction('images','readwrite').objectStore('images').delete(id);}catch{}}
function currentHotels(){return HotelJourney.scope(state,{selection:false,includeHistory:true});}
function syncTrip(){const f=$('#trip-form');for(const k of ['city','checkin','checkout','area'])f.elements[k].value=state.trip[k]||'';f.elements.functionalTest.checked=!!state.functionalTest;f.elements.city.readOnly=state.mode==='demo';$('#trip-title').textContent=state.trip.city?state.trip.city+'，慢一点。':'先设置目的地';$('#nav-hotels').textContent=comparisonHotels().length;$('#trip-summary').textContent=(state.trip.city||'目的地待设置')+' · '+(state.trip.checkin||'入住待定')+' — '+(state.trip.checkout||'退房待定')+' · 修改行程';document.querySelectorAll('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===state.mode);b.setAttribute('aria-pressed',String(b.dataset.mode===state.mode));});if($('#mode-context'))$('#mode-context').textContent=(state.mode==='demo'?'演示模式 · 虚构杭州案例，不参与我的行程':'我的行程 · '+(state.trip.city||'尚未设置城市'))+' · 当前 '+comparisonHotels().length+' 家候选'+(state.functionalTest?' · 功能测试：日期和预算仅作测试设定':'');}
function switchMode(mode){if(mode===state.mode)return;if(ocrBusy||(typeof aiBusy!=='undefined'&&aiBusy)||(typeof researchBusy!=='undefined'&&researchBusy)||(typeof discoveryBusy!=='undefined'&&discoveryBusy)||(typeof auditBusy!=='undefined'&&auditBusy)){toast('当前分析尚未完成，请稍后切换');return;}save();state=readState(slotKey(mode))||(mode==='demo'?demo():HotelJourney.migrate(null,demo().people));state.mode=mode;filterHotel='';filterPlatform='';if($('#dialog').open)closeDialog();save();render();}
function head(kicker,title,desc,buttons=''){return`<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div><div class="head-actions">${buttons}</div></div>`;}
function comparisonHotels(){return HotelJourney.scope(state);}
function banner(hotels=currentHotels()){return state.mode==='demo'?`<div class="banner"><strong>演示模式 · 虚构资料</strong><span>本模式的酒店、日期、价格与评价用于功能演示，单独保存，不参与“我的行程”。<button class="text-button" data-mode="trip">转到我的行程 ↗</button></span></div>`:`<div class="banner info"><strong>我的行程 · ${E(state.trip.city||'城市待设置')}</strong><span>当前 ${hotels.length} 家候选：${hotels.map(h=>E(h.name)).join('、')||'尚未加入酒店'}。房型、价格和设施未确认的内容不会当成已满足。${state.preferencesConfirmed?'':'同行偏好仍为可编辑预设，请核对。'}</span></div>`;}
function b(v,yes='有',no='无'){return v===true?`<span class="good">✓ ${yes}</span>`:v===false?`<span class="bad">${no}</span>`:'<span class="unknown">? 待确认</span>';}
function mold(v){return v===true?'<span class="bad">评价曾提及潮味／霉味</span>':v===false?'<span>已导入样本未提及<small class="small">不代表无此问题</small></span>':'<span class="unknown">待查证</span>';}
function hotelReasons(r){const h=r.hotel,f=r.facts;const lines=[];if(h.price!==null)lines.push(`¥${h.price}/晚，${state.people.every(p=>h.price<=p.budget)?'符合所有人的预算':'部分成员需要调整预算'}`);if(h.metro!==null)lines.push(`步行至地铁约 ${h.metro} 分钟`);if(f.opened)lines.push(`${f.opened} 年开业${f.renovated?'，'+f.renovated+' 年翻新':''}`);if(f.smart===true)lines.push('已确认对应房型有智能马桶');if(f.laundry===true)lines.push('已确认免费自助洗衣');return lines;}
function tradeoffs(r){const h=r.hotel,notes=[];if(h.metro>=8)notes.push('去地铁站步行较久');if(state.people.some(p=>HotelCriteria.freshness(r.facts,p.newnessPolicy,Number(state.trip.checkin?.slice(0,4))||new Date().getFullYear()).age>=HotelCriteria.policy(p.newnessPolicy).oldAfter))notes.push('超过部分同行人设定的较旧年数，请看维护与翻新范围');if(h.price!==null&&h.price>Math.min(...state.people.map(p=>p.budget))*.93)notes.push('接近同行人的预算上限');if(h.id==='h2'&&h.demo)notes.push('房间较紧凑，洗衣可能排队');if(h.id==='h3'&&h.demo)notes.push('洗衣房在另一栋');return notes.length?notes.join('；'):'目前资料未显示明显取舍，仍需检查房型与近期评价';}
function renderCard(r,i){const h=r.hotel;return`<article class="hotel-card recommended"><div class="card-top"><div><span class="rank">推荐 ${String(i+1).padStart(2,'0')}</span><h3>${E(h.name)}</h3><p class="sub">${E(h.area)} · ${E(h.room)}</p></div><div><div class="price">${h.price==null?'待查':'¥'+h.price}<small> / 晚</small></div><div class="price-note">每间价格 · ${h.demo?'演示报价':h.collector?'自动采集预览金额':'手动录入'}</div></div></div><div class="card-tags"><span class="tag ${h.demo?'demo':'real'}">${h.demo?'虚构演示酒店':h.collector?'平台自动采集':'用户录入'}</span>${r.facts.opened?`<span class="tag">${r.facts.opened} 年开业</span>`:''}${r.facts.smart===true?'<span class="tag">智能马桶</span>':''}<span class="tag">${h.evidence.length} 条依据</span></div><p class="rationale">${hotelReasons(r).map(E).join(' · ')}</p>${r.scores.map(s=>`<div class="member-score"><span>${E(s.name)}</span><div class="meter"><span style="width:${s.score}%"></span></div><span>${s.score}</span></div>`).join('')}<p class="disclaimer">偏好匹配分，不是酒店星级或客观评分。</p><div class="tradeoff">需要接受的取舍：${E(tradeoffs(r))}</div><div class="card-actions"><button class="text-button" data-action="evidence-hotel" data-id="${E(h.id)}">查看 ${h.evidence.length} 条依据 ↗</button><button class="small-button" data-action="edit-hotel" data-id="${E(h.id)}">编辑资料</button></div></article>`;}
function renderCompare(){const {rows,top,eligible}=HotelEngine.rank(comparisonHotels(),state.people,Number(state.trip.checkin?.slice(0,4))||new Date().getFullYear());const evCount=comparisonHotels().reduce((s,h)=>s+h.evidence.length,0);const topIDs=top.map(r=>r.hotel.id);const cols=rows.map(r=>r.hotel);
  const row=(name,fn)=>`<tr><th scope="row">${name}</th>${rows.map(r=>`<td class="${topIDs.includes(r.hotel.id)?'highlight':''}">${fn(r)}</td>`).join('')}</tr>`;
  $('#main').innerHTML=head('A STAY THAT FITS EVERYONE','这次，住哪一家？','把各自的在意，变成一起看得懂的选择。','<button class="secondary" data-action="add-hotel">＋ 添加候选酒店</button><button class="primary" data-action="add-evidence">＋ 导入评价截图</button><button class="secondary" data-action="add-policy">官方政策确认</button>')+banner(comparisonHotels())+`<div class="summary-line"><span><b>${comparisonHotels().length}</b>家候选</span><span><b>${state.people.length}</b>位同行人</span><span><b>${evCount}</b>条评价与资料</span><span><b>${eligible.length}</b>家满足已确认条件</span><span class="right">${E(state.trip.checkin)} — ${E(state.trip.checkout)}</span></div><div class="section-intro"><h2>更适合大家的选择</h2><button class="text-button" data-action="preferences">调整同行偏好 ↗</button></div><div class="recommendations">${top.length?top.map(renderCard).join(''):`<div class="cards-empty"><h3>目前没有满足全部必要条件的酒店</h3><p class="muted">看看下方对比表里的冲突与待确认项。你们可以补资料、调整要求，或添加新的候选。</p><button class="secondary" data-action="preferences">查看每个人的必要条件</button></div>`}${top.length===1?'<div class="cards-empty"><h3>暂时只有一家满足条件</h3><p class="muted">第二个位置留给符合要求的候选，不用勉强凑齐。</p></div>':''}</div><div class="section-intro"><h2>本次候选，一起比较</h2><small>浅绿色列为本次推荐 · 可横向滚动</small></div><div class="table-wrap"><table><thead><tr><th>对比维度</th>${cols.map(h=>`<th scope="col" class="${topIDs.includes(h.id)?'highlight':''}"><b>${E(h.name)}</b><span class="small">${h.demo?'虚构演示':h.collector?'平台自动采集':'用户录入'}</span></th>`).join('')}</tr></thead><tbody>${row('是否满足必要条件',r=>r.blocks.length?`<span class="bad">不符合</span><span class="small">${r.blocks.map(E).join('；')}</span>`:r.pending.length?`<span class="unknown">需确认</span><span class="small">${r.pending.map(E).join('；')}</span>`:'<span class="good">✓ 满足已确认条件</span>')}${row('每间每晚',r=>r.hotel.price==null?(r.hotel.referencePrice!=null?'<b>¥'+E(r.hotel.referencePrice)+'</b><span class="small">房型页参考价；含税应付价未核</span>':'待查'):`<b>¥${r.hotel.price}</b><span class="small">${E(r.hotel.terms)}<br>查询：${E(r.hotel.quoteDate)}</span>`)}${row('对应房型',r=>E(r.hotel.room))}${row('开业 / 翻新',r=>`${r.facts.opened||'开业待确认'} / ${r.facts.renovated||'翻新未查到'}${r.conflicts.some(k=>['opened','renovated'].includes(k))?'<span class="small bad">来源有冲突</span>':''}`)}${row('智能马桶',r=>b(r.facts.smart))}${row('免费自助洗衣',r=>b(r.facts.laundry))}${row('地铁步行',r=>r.hotel.metro==null?'待确认':r.hotel.metro+' 分钟<span class="small">录入估计值，非实时导航</span>')}${row('潮味 / 霉味',r=>mold(r.facts.mold))}${row('本地规则匹配分（非 AI）',r=>r.scores.map(s=>`${E(s.name)} ${s.score}`).join(' · '))}${row('评价依据',r=>`<button class="cell-evidence" data-action="evidence-hotel" data-id="${E(r.hotel.id)}">查看 ${r.hotel.evidence.length} 条 ↗</button>${r.conflicts.length?'<span class="small bad">部分资料冲突，需核对</span>':''}`)}${row('管理候选',r=>`<button class="small-button" data-action="edit-hotel" data-id="${E(r.hotel.id)}">编辑</button> <button class="text-button" data-action="add-evidence" data-id="${E(r.hotel.id)}">加评价</button>`)}</tbody></table></div><p class="disclaimer">本地规则预览方式：先检查所有人的必要条件，再优先照顾偏好匹配分最低的成员；同分时比较平均分。缺失信息不推定为“有”，评价未提及霉味也不代表没有。<button class="text-button" data-action="method">查看计算方式</button></p><div class="footer-note">STAY TOGETHER / 第一期 · 透明规则推荐 + 可选截图文字识别 · 未接入通用大模型</div>`;
}
function renderPreferences(){const fields=[['newness','设施新旧'],['facilities','房内设施与洗衣'],['price','价格'],['transit','地铁交通']];$('#main').innerHTML=head('DIFFERENT WISHES, ONE TRIP','你的在意，也值得被记住。','没有默认正确的标准，每个人都可以说出自己的要求。')+`<div class="banner info"><strong>先试试预设</strong><span>选择预设会替换当前同行偏好，酒店和评价保持不变。</span></div><div class="pill-row"><button data-action="preset" data-id="balanced">◌ 我爱新设施，朋友重交通</button><button data-action="preset" data-id="comfort">◌ 大家都想住舒服一些</button><button data-action="preset" data-id="tight">◌ 预算紧张，体验条件冲突</button></div><form id="preferences-form"><div class="preferences-grid" style="margin-top:20px">${state.people.map((p,i)=>`<section class="panel"><div class="person-title"><span class="avatar ${i%2?'purple':''}">${i+1}</span><input name="${i}-name" value="${E(p.name)}" aria-label="同行人 ${i+1} 的称呼" required maxlength="20"></div><div class="fields"><label>可接受的每间每晚价格（元）<input type="number" min="1" max="100000" step="1" name="${i}-budget" value="${p.budget}" required></label><label class="check-label"><input type="checkbox" name="${i}-budgetHard" ${p.budgetHard?'checked':''}>预算是必要条件，超出就排除</label><p class="field-heading">我的必要条件</p>${[['requireSmart','对应房型必须有智能马桶'],['requireLaundry','必须有免费自助洗衣'],['avoidMold','排除已有潮味／霉味反馈的候选']].map(([k,t])=>`<label class="check-label"><input type="checkbox" name="${i}-${k}" ${p[k]?'checked':''}>${t}</label>`).join('')}<label class="check-label"><input type="checkbox" name="${i}-transitHard" ${p.transitHard?'checked':''}>限制步行到地铁的时间</label><label>地铁步行上限（分钟）<input type="number" min="1" max="120" name="${i}-maxMetro" value="${p.maxMetro}" required></label><p class="field-heading">加分项的重要程度</p>${fields.map(([k,t])=>`<label><span class="range-label"><span>${t}</span><output id="out-${i}-${k}">${p.weights[k]}</output></span><input type="range" min="0" max="5" step="1" name="${i}-weight-${k}" value="${p.weights[k]}" data-output="out-${i}-${k}"></label>`).join('')}<p class="muted">0 = 不在意，5 = 非常在意。预算均按每间计算，不是人均分摊。</p></div></section>`).join('')}</div><div class="bottom-bar"><button class="primary" type="submit">保存偏好，回到酒店对比 →</button><button class="secondary" type="button" data-action="add-person">＋ 增加同行人</button></div></form><div class="help-box"><b>分歧不需要被平均掉。</b><p>必要条件有冲突时，系统会明确告诉你；资料不足时，先补信息。偏好匹配分只是解释排序的方法，不预测满意度。</p></div>`;}
function renderEvidence(){const hotels=filterHotel?currentHotels().filter(h=>h.id===filterHotel):currentHotels();const records=hotels.map(h=>`<article class="evidence-card"><div class="evidence-head"><b>${E(h.name)} · 酒店资料卡</b><span class="tag ${h.demo?'demo':'real'}">${h.demo?'虚构演示':'用户填写 · 未独立核验'}</span></div><p class="evidence-meta">房型：${E(h.room||'未注明')} · 查询日期：${E(h.quoteDate||'未提供')}</p><p>${h.price==null?'价格待确认':'¥'+h.price+'/晚'} · ${E(h.terms||'预订条件未提供')}</p>${h.demo?'<span class="evidence-meta">演示设定，无真实来源。</span>':link(h.source)}<div style="text-align:right"><button class="text-button" data-action="edit-hotel" data-id="${E(h.id)}">核对或修改基础字段 ↗</button></div></article>`).join('');const items=hotels.flatMap(h=>h.evidence.filter(e=>!filterPlatform||e.platform===filterPlatform).map(e=>({h,e})));$('#main').innerHTML=head('EVERY REASON HAS A SOURCE','好的选择，有据可查。','保留原文与截图，让“推荐”可以被你亲自检查。','<button class="primary" data-action="add-evidence">＋ 导入截图 / 文字</button><button class="secondary" data-action="add-policy">官方政策确认</button>')+banner()+`<div class="filter-bar"><select id="filter-hotel" aria-label="按酒店筛选"><option value="">所有酒店</option>${currentHotels().map(h=>`<option value="${E(h.id)}" ${h.id===filterHotel?'selected':''}>${E(h.name)}</option>`).join('')}</select><select id="filter-platform" aria-label="按来源筛选"><option value="">所有来源</option>${['小红书','大众点评','抖音','携程','同程','酒店资料','其他'].map(p=>`<option ${p===filterPlatform?'selected':''}>${p}</option>`).join('')}</select><span class="muted">共 ${items.length} 条</span></div><div class="evidence-list">${!filterPlatform?records:''}${items.length?items.map(({h,e})=>e.kind==='platform_policy'?policyEvidenceHTML(h,e):`<article class="evidence-card"><div class="evidence-head"><b>${E(h.name)}</b><span class="tag ${e.demo?'demo':'real'}">${e.demo?'演示评价 · 虚构':e.webResearch?(e.confirmed?'检索摘要 · 用户已核对':'检索摘要 · 待核对'):'用户导入 · 已确认'}</span></div><div class="evidence-meta">${E(e.platform)} · ${E(e.date||'日期未提供')} · ${E(e.room||'适用房型未注明')}</div><blockquote>${E(e.text)}</blockquote><div class="evidence-flags">${Object.entries(e.claims||{}).filter(([,v])=>v!==null&&v!=='').map(([k,v])=>`${E(labels[k]||k)}：${typeof v==='boolean'?(k==='mold'?(v?'提及':'明确说未闻到'):(v?'有':'无')):E(v)}`).join(' · ')||'仅保存原文，未确认设施字段'}</div>${e.webResearch?`<button class="small-button" data-review-research="${E(e.id)}">核对摘要与来源 ↗</button> `:''}${e.image?`<button class="small-button" data-action="view-image" data-id="${E(e.id)}">查看导入截图 ↗</button> `:''}${e.demo?'<span class="evidence-meta">这是为演示编写的材料，无真实平台链接。</span>':link(e.source)}<div style="text-align:right"><button class="danger-button" data-action="delete-evidence" data-hotel="${E(h.id)}" data-id="${E(e.id)}">删除这条资料</button></div></article>`).join(''):'<div class="empty">还没有这类资料。可以先导入一张截图。</div>'}</div>`;}
function renderGuide(){$('#main').innerHTML=head('FROM DEMO TO YOUR NEXT TRIP','先换一家，就能开始。','每次只替换一小部分，用你自己的旅行慢慢验证。')+`<div class="guide-grid"><section class="panel"><span class="step-num">01</span><h3>写下你们真正的要求</h3><p>在左侧修改行程；在“同行人的偏好”里填写每个人的预算、必要条件和加分项。可以先用预设，再微调。</p><button class="secondary" data-action="preferences">填写同行偏好</button></section><section class="panel"><span class="step-num">02</span><h3>添加第一家真实酒店</h3><p>点击“添加真实酒店”，填写酒店名、具体房型、报价条件和来源。拿不准的项目保持“待确认”，演示酒店也可以逐一删除。</p><button class="secondary" data-action="add-hotel">添加真实酒店</button></section><section class="panel"><span class="step-num">03</span><h3>导入一张评价截图</h3><p>选择对应酒店，上传图片，点击“AI 理解这张截图”。核对文字后，只确认这条材料确实提到的设施；资料适用的房型也需要核实。</p><button class="secondary" data-action="add-evidence">导入第一张截图</button></section><section class="panel"><span class="step-num">04</span><h3>一起看推荐与证据</h3><p>回到酒店对比，检查推荐理由、每个人的理由和取舍。对照原文找错，再补一条新资料看看推荐如何变化。</p><button class="secondary" data-action="compare">查看对比结果</button></section></div><div class="help-box"><h3>第一期已经支持什么</h3><p>偏好编辑、酒店资料编辑、截图保存与可选文字识别、证据核对、条件冲突提示、两家推荐、本地保存、导入导出。</p><p>本版采用透明规则推荐，尚未接入通用大模型。它不会自动搜取小红书、大众点评或抖音内容，也不会实时查询房价。链接只用于追溯，截图识别是本地文字识别，不理解视频。</p><p>截图和私人资料保存在当前设备的浏览器中，网站后台不接收这些文件。首次识别需联网下载文字识别组件。分享网址不会共享你录入的资料；可以导出备份，在另一个设备导入。</p></div><div class="bottom-bar"><button class="secondary" id="guide-export" data-action="export">导出当前行程和截图</button><button class="danger-button" data-action="reset">重新载入演示场景</button></div>`;}
function render(){if(!['compare','preferences','evidence','guide'].includes(view))view='compare';syncTrip();document.querySelectorAll('[data-view]').forEach(a=>a.classList.toggle('active',a.dataset.view===view));({compare:renderCompare,preferences:renderPreferences,evidence:renderEvidence,guide:renderGuide}[view])();if(storageRecoveryErrors.size){$('#main').insertAdjacentHTML('afterbegin',storageRecoveryHTML());$('#storage-status').textContent='资料恢复异常 · 已暂停保存，原内容保留';}}
function go(v){if(location.hash==='#'+v){view=v;render();}else location.hash=v;}
window.addEventListener('hashchange',()=>{view=location.hash.slice(1);render();window.scrollTo({top:0,behavior:'smooth'});});
function showDialog(title,html){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=html;pendingImage=null;$('#dialog').showModal();}
function closeDialog(){$('#dialog').close();pendingImage=null;}
$('#dialog-close').onclick=closeDialog;
$('#guide-top').onclick=()=>go('guide');
function triOptions(v){return`<option value="" ${v==null?'selected':''}>待确认 / 未提及</option><option value="true" ${v===true?'selected':''}>有</option><option value="false" ${v===false?'selected':''}>无</option>`;}
function hotelDialog(id){const h=state.hotels.find(h=>h.id===id)||{id:uid(),name:'',area:'',room:'',price:null,metro:null,source:'',terms:'',quoteDate:today(),city:state.trip.city,demo:state.mode==='demo',facts:{opened:null,renovated:null,smart:null,laundry:null,mold:null},evidence:[]};const exists=state.hotels.some(x=>x.id===h.id);
showDialog(exists?'编辑酒店资料':'添加一家真实酒店',`${h.demo?'<div class="notice">这是独立保存的虚构演示酒店。真实酒店请在“我的行程”中添加。</div>':''}<form id="hotel-form" data-id="${E(h.id)}"><div class="form-grid"><label>城市<input name="city" maxlength="40" value="${E(h.city||state.trip.city)}" required></label><label>酒店名称<input name="name" maxlength="80" value="${E(h.name)}" required></label><label>位置描述<input name="area" maxlength="120" value="${E(h.area)}"></label><label class="wide">具体房型 / 面积<input name="room" maxlength="160" value="${E(h.room)}" placeholder="如：行政大床房，42㎡"></label><label>每间每晚含税价格（元）<input type="number" min="1" max="100000" step="0.01" name="price" value="${h.price??''}" placeholder="不确定留空"></label><label>步行至地铁（分钟）<input type="number" min="0" max="180" name="metro" value="${h.metro??''}"></label><label>开业年份<input type="number" min="1900" max="2100" name="opened" value="${h.facts.opened??''}"></label><label>最近翻新年份<input type="number" min="1900" max="2100" name="renovated" value="${h.facts.renovated??''}"></label><label>该房型有智能马桶<select name="smart">${triOptions(h.facts.smart)}</select></label><label>有免费自助洗衣<select name="laundry">${triOptions(h.facts.laundry)}</select></label><label>已查材料是否提及潮味／霉味<select name="mold"><option value="" ${h.facts.mold==null?'selected':''}>尚未查证</option><option value="true" ${h.facts.mold===true?'selected':''}>有相关反馈</option><option value="false" ${h.facts.mold===false?'selected':''}>已查样本未提及（非保证）</option></select></label><label>报价查询日期<input type="date" name="quoteDate" value="${E(h.quoteDate)}"></label><label class="wide">早餐 / 取消 / 税费条件<input name="terms" maxlength="240" value="${E(h.terms)}" placeholder="如：含双早，免费取消至11月10日，价格含税"></label><label class="wide">资料来源链接<input type="url" name="source" value="${E(h.source)}" placeholder="https://..."></label></div><p class="disclaimer">以上均按你提供的资料保存，不是系统独立核验。明确查到的才填写；未知字段保留为空。</p><div class="dialog-footer">${exists?`<button type="button" class="danger-button" data-action="delete-hotel" data-id="${E(h.id)}">删除这家酒店</button>`:''}<button class="primary" type="submit">${!exists&&HotelJourney.tripScope(state.trip,state.people)||exists&&HotelJourney.belongs(h,state.trip,state.people)?'保存到本次行程':'保存历史资料'}</button></div></form>`);
}
// Official policy is scoped to a captured package, never a guest review or a
// global facility fact. These helpers do not update quotes, prices or people.
function policyOfferChoices(h,trip=state.trip){
 if(!h||state.mode!=='trip'||(trip.children??0)!==0||!window.StayQuoteEvidence)return [];
 const Q=window.StayQuoteEvidence,b=Q.clean(h.quoteBundle,trip,h.name);
 return (b?.offers||[]).filter(o=>Q.key(o.room)===Q.key(h.room));
}
function policyOfferStatus(h,offer){
 if(!offer)return {error:'当前行程和目标房型没有可对应的已采套餐，请先查价并选定房型。'};
 const breakfastCount=window.StayQuoteEvidence.breakfastCount(offer),paymentBasis=HotelEngine.policyPaymentBasis(offer.payment);
 if(breakfastCount===null)return {error:'该套餐早餐份数未核清，不能保存政策确认；请先取得明确的餐食资料。'};
 if(!paymentBasis)return {error:'该套餐付款方式未注明或有冲突，不能猜测；请先取得明确的在线付／到店付资料。'};
 return {breakfastCount,paymentBasis,error:''};
}
function policyScopeHTML(scope,offer){
 if(!scope)return '<p class="notice">政策适用范围不完整，暂不作为当前条件依据。</p>';
 const fields=[['预订平台',scope.provider==='ctrip'?'携程':'同程'],['具体房型',scope.room],['入住／退房',scope.checkin+' — '+scope.checkout],['间数／人数',scope.rooms+'间 / '+scope.adults+'成人 / 无儿童'],['早餐',scope.breakfastCount+'份 / 每间每日'],['付款方式',scope.paymentBasis==='online'?'在线付':'到店付']];
 return '<div class="form-grid policy-scope">'+fields.map(([label,value])=>'<label>'+E(label)+'<input readonly value="'+E(value)+'"></label>').join('')+'</div><p class="evidence-meta">套餐标识：'+E(scope.offerId)+(offer?' · 页面原文：'+E(offer.breakfastText)+' / '+E(offer.payment):'')+'</p>';
}
function policyEvidenceHTML(h,e){
 const scope=HotelEngine.cleanPolicyScope(e.policyScope),result=HotelEngine.policyFactsFor(h,state.trip),applied=result.applied.some(x=>x.id===e.id),inactive=result.inactive.find(x=>x.id===e.id),conflict=result.conflicts.some(k=>Object.hasOwn(e.claims||{},k));
 const status=conflict?'政策记录有冲突，相关条件仍待核实':applied?'当前选中套餐适用':'当前未应用：'+(inactive?.reason||'适用范围未核清');
 const precondition=!scope?'适用前提未核清，不作为当前条件依据。':scope.requiresPaidConfirmed?'仅在线支付且酒店／供应商确认后成立；本记录不代表已经付款或确认，也不要求现在付款。':'官方答复未设置“在线已付且确认”前提；其他限制仍以原文为准。';
 const flags=['invoice','lateCheckin'].filter(k=>typeof e.claims?.[k]==='boolean').map(k=>(k==='invoice'?'所需发票':'所录晚到保房安排')+'：'+(e.claims[k]?'官方答复支持（限范围及前提）':'官方明确不支持')).map(E).join(' · ');
 return '<article class="evidence-card policy-evidence"><div class="evidence-head"><b>'+E(h.name)+'</b><span class="tag real">官方政策确认 · 非住客评价</span></div><p class="evidence-meta">'+E(e.platform)+' · 核实日期 '+E(e.date||'未提供')+'</p>'+policyScopeHTML(scope)+'<p class="'+(applied&&!conflict?'good':'unknown')+'">'+E(status)+'</p><p>'+E(precondition)+'</p><div class="evidence-flags">'+flags+'</div><blockquote style="white-space:pre-wrap">'+E(e.text)+'</blockquote>'+link(e.source)+'<div style="text-align:right"><button class="danger-button" data-action="delete-evidence" data-hotel="'+E(h.id)+'" data-id="'+E(e.id)+'">删除这条资料</button></div></article>';
}
function makePolicyEvidence(h,offerId,fields){
 if(state.mode!=='trip')throw Error('请在“我的行程”中录入真实官方政策。');
 const choices=policyOfferChoices(h),matches=choices.filter(o=>o.id===offerId);
 if(matches.length!==1)throw Error('该套餐已不属于当前行程和目标房型，或标识重复；请重新选定酒店与套餐。');
 const offer=matches[0],status=policyOfferStatus(h,offer);if(status.error)throw Error(status.error);
 if(!['none','paid_confirmed'].includes(fields.precondition))throw Error('请明确官方答复是否以在线已付且酒店／供应商确认为前提。');
 const requiresPaidConfirmed=fields.precondition==='paid_confirmed';
 if(requiresPaidConfirmed&&status.paymentBasis!=='online')throw Error('到店付套餐不能套用“在线已付且确认”的政策。');
 const claims={};for(const key of ['invoice','lateCheckin']){const value=fields[key]??'';if(!['','true','false'].includes(value))throw Error('请重新选择政策确认结果。');if(value!=='')claims[key]=value==='true';}
 if(!Object.keys(claims).length)throw Error('至少确认发票或晚到保房一项，其余保持待确认。');
 const text=String(fields.text||'').trim(),invoiceDetail=String(fields.invoiceDetail||'').trim(),lateDetail=String(fields.lateDetail||'').trim(),date=String(fields.date||'');
 if(!text||text.length>10000)throw Error('请填写官方答复原文，最多10000字。');
 if(Object.hasOwn(claims,'invoice')&&(!invoiceDetail||invoiceDetail.length>300))throw Error('请写明所确认的票种、开具方或申请方式，最多300字。');
 if(Object.hasOwn(claims,'lateCheckin')&&(!lateDetail||lateDetail.length>300))throw Error('请写明所确认的到店时段和保房安排，最多300字。');
 if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isFinite(Date.parse(date))||new Date(date).toISOString().slice(0,10)!==date)throw Error('请填写有效核实日期。');
 if(fields.confirmed!==true)throw Error('请核对官方原文、套餐范围和适用前提后勾选确认。');
 const source=HotelEngine.cleanPolicySource(fields.source,offer.provider);if(!source)throw Error('请填写该预订平台的HTTPS官方来源链接，不能使用其他平台或非官方域名。');
 const scope=HotelEngine.cleanPolicyScope({version:1,provider:offer.provider,hotel:h.name,room:offer.room,checkin:offer.checkIn,checkout:offer.checkOut,rooms:offer.rooms,adults:offer.adults,children:0,breakfastCount:status.breakfastCount,paymentBasis:status.paymentBasis,requiresPaidConfirmed,offerId:offer.id});
 if(!scope)throw Error('政策范围不完整，请重新核对当前套餐。');
 const notes=['【平台官方政策确认，非住客评价】',...(Object.hasOwn(claims,'invoice')?['所需发票：'+(claims.invoice?'官方答复支持':'官方明确不支持')+'；'+invoiceDetail]:[]),...(Object.hasOwn(claims,'lateCheckin')?['晚到保房：'+(claims.lateCheckin?'官方答复支持':'官方明确不支持')+'；'+lateDetail]:[]),'适用范围：'+(offer.provider==='ctrip'?'携程':'同程')+'；'+h.name+'；'+scope.room+'；'+scope.checkin+'至'+scope.checkout+'；'+scope.rooms+'间/'+scope.adults+'成人；'+scope.breakfastCount+'份早餐；'+(scope.paymentBasis==='online'?'在线付':'到店付'),'适用前提：'+(requiresPaidConfirmed?'仅在线支付且酒店／供应商确认后成立':'官方答复未设置在线已付且确认前提')+'；本记录不代表已订房、已付款或已确认。','核实日期：'+date,'官方答复原文：',text].join('\n');
 if(notes.length>12000)throw Error('政策记录过长，请保留关键原文。');
 return {id:uid(),kind:'platform_policy',confirmed:true,claims,policyScope:scope,text:notes,source,date,room:scope.room,platform:offer.provider==='ctrip'?'携程':'同程',demo:false,image:null};
}
function policyDialog(id,offerId){
 if(state.mode!=='trip'){toast('请切换到“我的行程”后录入真实官方政策');return;}
 const hotels=currentHotels(),h=hotels.find(h=>h.id===id)||hotels.find(h=>policyOfferChoices(h).length)||hotels[0];
 if(!h){toast('请先加入酒店并采集目标房型套餐');return;}
 const offers=policyOfferChoices(h),offer=offers.find(o=>o.id===(offerId||h.quoteBundle?.selected_offer_id))||offers[0],status=policyOfferStatus(h,offer),scope=!status.error?HotelEngine.cleanPolicyScope({version:1,provider:offer.provider,hotel:h.name,room:offer.room,checkin:offer.checkIn,checkout:offer.checkOut,rooms:offer.rooms,adults:offer.adults,children:0,breakfastCount:status.breakfastCount,paymentBasis:status.paymentBasis,requiresPaidConfirmed:false,offerId:offer.id}):null;
 const current=offer?.id===h.quoteBundle?.selected_offer_id;
 showDialog('官方政策确认',`<form id="policy-form"><p class="muted">先选酒店与套餐，再填写官方答复。切换选择会清空未保存内容；不会更换当前分析套餐。</p><div class="form-grid"><label>酒店<select name="hotel" required>${hotels.map(x=>`<option value="${E(x.id)}" ${h.id===x.id?'selected':''}>${E(x.name)}</option>`).join('')}</select></label><label>对应的已采套餐<select name="offer" required>${offers.length?offers.map(o=>`<option value="${E(o.id)}" ${o.id===offer?.id?'selected':''}>${E(o.platform)} · ${E(o.room)} · ${E(o.breakfastText)} · ${E(o.payment||'付款未注明')} · ${o.listNightly==null?'参考价未取得':'¥'+E(o.listNightly)+'/间/晚'}</option>`).join(''):'<option value="">没有当前行程与目标房型的套餐</option>'}</select></label></div>${scope?policyScopeHTML(scope,offer):'<p class="notice" role="alert">'+E(status.error||'适用范围不完整')+'</p>'}${scope&&!current?'<p class="notice">所选套餐不是当前分析套餐。可保存为该套餐的政策来源，当前不会应用；只有选中同一套餐且范围一致时才适用。</p>':''}<div class="form-grid"><label>所需发票<select name="invoice"><option value="">待确认，不写入结论</option><option value="true">官方明确支持</option><option value="false">官方明确不支持</option></select></label><label>票种、开具方／申请方式<input name="invoiceDetail" maxlength="300" placeholder="如：电子普通发票，由谁开具、如何申请"></label><label>晚到保房安排<select name="lateCheckin"><option value="">待确认，不写入结论</option><option value="true">官方明确支持所录时段</option><option value="false">官方明确不支持所录时段</option></select></label><label>到店时段与保房安排<input name="lateDetail" maxlength="300" placeholder="如：23:00—24:00抵店，是否整晚保留"></label><label class="wide">适用前提<select name="precondition" required><option value="">请选择官方答复的前提</option><option value="none">官方答复未设置在线已付且确认前提</option><option value="paid_confirmed" ${status.paymentBasis!=='online'?'disabled':''}>仅在线支付且酒店／供应商确认后成立</option></select></label><label>核实日期<input type="date" name="date" value="${E(today())}" required></label><label>平台官方来源链接<input type="url" name="source" required placeholder="${offer?.provider==='tongcheng'?'https://www.ly.com/…':'https://hotels.ctrip.com/…'}"></label><label class="wide">官方政策／客服答复原文<textarea name="text" maxlength="10000" required placeholder="粘贴关键原文；客服新报价只作为原文保留，不会覆盖已有房价。"></textarea></label><label class="check-label wide"><input type="checkbox" name="confirmed" required>我已核对官方原文、酒店、平台、房型、日期、人数、早餐和付款前提；保存不代表已下单、已付款或已获酒店确认</label></div><div class="dialog-footer"><button class="primary" type="submit" ${status.error||!scope?'disabled':''}>保存官方政策确认</button></div></form>`);
}
function savePolicyForm(form){
 const data=new FormData(form),h=currentHotels().find(h=>h.id===data.get('hotel'));if(!h){toast('所选酒店不属于当前行程，请重新选择');return false;}
 try{const fields=Object.fromEntries(['invoice','invoiceDetail','lateCheckin','lateDetail','precondition','date','source','text'].map(k=>[k,String(data.get(k)||'')]));fields.confirmed=data.has('confirmed');const evidence=makePolicyEvidence(h,String(data.get('offer')||''),fields);h.evidence.push(evidence);if(!save()){h.evidence.pop();return false;}closeDialog();filterHotel=h.id;filterPlatform='';go('evidence');toast('官方政策已保存，仅按对应套餐和前提应用');return true;}catch(error){toast(error.message||'政策确认未能保存，请核对范围');return false;}
}
function evidenceDialog(id){if(!currentHotels().length){toast('先添加一家酒店，再导入评价');hotelDialog();return;}showDialog('导入评价，留下原始依据',`<button type="button" class="secondary" data-action="add-policy" data-id="${E(id||'')}">官方客服或政策答复？使用官方政策确认 →</button><form id="evidence-form"><div class="form-grid"><label>这条资料属于哪家酒店<select name="hotel" required>${currentHotels().map(h=>`<option value="${E(h.id)}" ${id===h.id?'selected':''}>${E(h.name)}${h.demo?'（演示候选）':''}</option>`).join('')}</select></label><label>来自哪里<select name="platform"><option>小红书</option><option>大众点评</option><option>抖音</option><option>酒店资料</option><option>其他</option></select></label><div class="wide"><label class="upload-zone"><span style="font-size:23px;color:var(--green)">＋</span><span>选择评价截图 · PNG / JPG / WebP · 最大 10 MB</span><input type="file" id="evidence-file" accept="image/png,image/jpeg,image/webp"></label><img id="upload-preview" class="upload-preview" alt="已导入的评价截图预览" hidden><button type="button" class="secondary" id="ocr-button" disabled>识别截图文字</button><div id="ocr-status" class="ocr-status" aria-live="polite">也可以直接粘贴评价文字。截图会在你确认保存后保存在当前浏览器。</div></div><div class="wide"><a class="quote-source" href="demo-review.png" download="演示评价截图.png">下载一张虚构演示截图，先试一次 ↗</a></div><label class="wide">评价原文 / 识别结果<textarea name="text" id="evidence-text" required maxlength="12000" placeholder="识别后请核对原文；也可以手动粘贴。保存前请确认没有认错酒店或房型。"></textarea></label><label>评价日期<input type="date" name="date"></label><label>评价对应的房型<input name="room" maxlength="120" placeholder="不清楚可填“未注明”"></label><label class="wide">原始分享链接<input type="url" name="source" placeholder="用于回看，系统不会自动读取链接"></label><div class="wide"><p class="field-heading">这条材料明确说明了什么？</p><p class="muted">只确认适用于上方酒店和目标房型的信息；关键词建议可能出错，请核对。未提及保持待确认。</p><button type="button" class="text-button" id="suggest-claims">从文字提示可能的字段（需核对） ↗</button><div class="fact-controls"><label>智能马桶<select name="smart">${triOptions(null)}</select></label><label>马桶清洗功能（臀洗／妇洗）<select name="smartWash">${triOptions(null)}</select><span class="muted">仅座圈加热不能证明有清洗功能；原文明示有／无才填写。</span></label><label>免费自助洗衣<select name="laundry">${triOptions(null)}</select></label><label>潮味 / 霉味<select name="mold"><option value="">未提及 / 不明确</option><option value="true">提及有潮味 / 霉味</option><option value="false">明确说未闻到</option></select></label><label>开业年份<input type="number" name="opened" min="1900" max="2100" placeholder="只有明确说明才填"></label></div></div><label class="check-label wide"><input type="checkbox" name="isDemo">这条资料是演示或虚构内容（不会标为真实用户评价）</label><label class="check-label wide"><input type="checkbox" name="confirmed" required>我已核对原文、酒店与房型；上方确认字段可用于推荐</label></div><div class="dialog-footer"><button class="primary" type="submit" id="save-evidence">确认并保存依据</button></div></form>`);}
async function loadOCR(){if(window.Tesseract)return window.Tesseract;if(!loadOCR.promise)loadOCR.promise=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js';const t=setTimeout(()=>{s.remove();loadOCR.promise=null;reject(new Error('加载超时'));},20000);s.onload=()=>{clearTimeout(t);resolve(window.Tesseract);};s.onerror=()=>{clearTimeout(t);loadOCR.promise=null;reject(new Error('组件未能加载'));};document.head.appendChild(s);});return loadOCR.promise;}
async function recognize(){if(!pendingImage||ocrBusy)return;const target=pendingImage;ocrBusy=true;const btn=$('#ocr-button'),status=$('#ocr-status');btn.disabled=true;btn.textContent='正在识别…';let worker;try{status.textContent='首次使用需下载识别组件和语言文件，图片在浏览器内处理。';const T=await loadOCR();worker=await T.createWorker('chi_sim+eng',1,{logger:m=>{if(status.isConnected)status.textContent=m.status==='recognizing text'?`正在识别文字 ${Math.round((m.progress||0)*100)}%`:'正在准备文字识别…';}});const ret=await worker.recognize(target);if(!status.isConnected)return;$('#evidence-text').value=ret.data.text;status.textContent='识别完成。请对照截图修正文字，再核对下方字段。';suggestClaims();}catch{if(status.isConnected)status.textContent='文字识别暂时不可用。截图仍可保存，请手动粘贴或摘录关键评价。';}finally{if(worker)await worker.terminate();ocrBusy=false;if(btn.isConnected){btn.disabled=false;btn.textContent='重新识别截图文字';}}}
function suggestClaims(){const f=$('#evidence-form');if(!f)return;const h=state.hotels.find(h=>h.id===f.elements.hotel.value);const out=HotelClaims.suggest(f.elements.text.value,{hotelName:h?.name,hotelNames:currentHotels().map(h=>h.name),room:f.elements.room.value||h?.room});for(const[k,v]of Object.entries(out.claims))f.elements[k].value=v===null?'':String(v);if(/演示评价|完全虚构|测试截图/.test(f.elements.text.value))f.elements.isDemo.checked=true;let box=$('#local-claims-result');if(!box){box=document.createElement('div');box.id='local-claims-result';box.className='notice';$('#suggest-claims').after(box);}box.textContent=out.notes.length?out.notes.join(' '):'已提示原文中的明确陈述，请核对酒店和房型后再保存。';f.elements.confirmed.checked=false;toast('本地字段提示已更新；不确定项保留待确认');}
async function exportData(){try{const images={};for(const h of state.hotels)for(const e of h.evidence)if(e.image){const d=await imageGet(e.image);if(d)images[e.image]=d;}const data={...state,images,exportedAt:new Date().toISOString()};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='住一起-行程备份.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('已导出行程与截图备份');}catch{toast('导出失败，请重试');}}
$('#export').onclick=exportData;$('#import').onclick=()=>$('#import-file').click();
$('#import-file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>40*1024*1024)throw Error();let data=JSON.parse(await f.text());if(!validState(data))throw Error();if(!confirm('用这个备份替换当前行程？建议先导出当前资料。'))return;for(const[k,v]of Object.entries(data.images||{})){if(typeof v==='string'&&/^data:image\/(png|jpeg|webp);base64,/.test(v))await imagePut(k,v);}delete data.images;if(!data.mode)data=HotelJourney.migrate(data,demo().people);if(data.mode==='trip')data.hotels=data.hotels.filter(h=>!h.demo);else data.hotels=data.hotels.filter(h=>h.demo);state=data;save();render();toast('备份已导入');}catch{toast('无法导入：请选择有效的住一起 JSON 备份文件');}finally{e.target.value='';}};
document.addEventListener('input',e=>{if(e.target.name==='city'&&e.target.closest('#trip-form')&&HotelJourney.city(e.target.value)!==HotelJourney.city(state.trip.city)){const f=$('#trip-form');f.elements.checkin.value='';f.elements.checkout.value='';f.elements.area.value='';}if(e.target.dataset.output)document.getElementById(e.target.dataset.output).textContent=e.target.value;});
document.addEventListener('change',async e=>{
  if(e.target.closest?.('#policy-form')&&['hotel','offer'].includes(e.target.name)){const form=e.target.closest('#policy-form');policyDialog(form.elements.hotel.value,e.target.name==='offer'?e.target.value:undefined);return;}
  if(e.target.closest?.('#evidence-form')&&(e.target.name==='hotel'||e.target.id==='evidence-file')){const form=e.target.closest('#evidence-form');form.elements.smartWash.value='';form.elements.confirmed.checked=false;}
  if(e.target.id==='filter-hotel'){filterHotel=e.target.value;renderEvidence();}
  if(e.target.id==='filter-platform'){filterPlatform=e.target.value;renderEvidence();}
  if(e.target.id==='evidence-file'){const f=e.target.files[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>10*1024*1024){toast('请选择 10 MB 以内的 PNG、JPG 或 WebP 图片');e.target.value='';return;}try{const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f);});const img=await new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=reject;im.src=data;});const scale=Math.min(1,2200/img.width,9000/img.height);const cv=document.createElement('canvas');cv.width=Math.max(1,Math.round(img.width*scale));cv.height=Math.max(1,Math.round(img.height*scale));cv.getContext('2d').drawImage(img,0,0,cv.width,cv.height);pendingImage=cv.toDataURL('image/jpeg',.9);$('#upload-preview').src=pendingImage;$('#upload-preview').hidden=false;$('#ocr-button').disabled=false;$('#ocr-status').textContent='截图已准备好。可识别文字，或手动摘录；确认保存后才会加入证据库。';}catch{toast('图片读取失败，请换一张截图');}}
});
document.addEventListener('click',async e=>{if(e.target.id==='ocr-button'){recognize();return;}if(e.target.id==='suggest-claims'){suggestClaims();return;}const modeButton=e.target.closest('[data-mode]');if(modeButton){switchMode(modeButton.dataset.mode);return;}const btn=e.target.closest('[data-action]');if(!btn)return;const a=btn.dataset.action,id=btn.dataset.id;
  if(['compare','preferences','guide'].includes(a))go(a);
  if(a==='export')exportData();
  if(a==='add-hotel')hotelDialog();if(a==='edit-hotel')hotelDialog(id);if(a==='add-evidence')evidenceDialog(id);if(a==='add-policy')policyDialog(id);
  if(a==='join-history'){if(!HotelJourney.tripScope(state.trip,state.people)){toast('请先填写本次城市、入住退房日期和人数，再加入候选');return;}const old=state.hotels.find(h=>h.id===id&&!h.demo);if(!old)return;const active=comparisonHotels().map(h=>h.id),joined=HotelJourney.join(old,state.trip,state.people);state.hotels=state.hotels.map(h=>h.id===id?joined:h);state.hotelSelection=[...new Set([...active,id])];delete state.aiResult;save();render();toast('已加入本次行程；旧报价已归档，请核对当前房价和套餐条件');}
  if(a==='evidence-hotel'){filterHotel=id;filterPlatform='';go('evidence');}
  if(a==='delete-hotel'){if(confirm('删除这家候选酒店及其评价？')){const h=state.hotels.find(h=>h.id===id);for(const ev of h?.evidence||[])if(ev.image)imageDelete(ev.image);state.hotels=state.hotels.filter(h=>h.id!==id);save();closeDialog();render();toast('候选酒店已删除');}}
  if(a==='delete-evidence'){if(confirm('删除这条资料？')){const h=state.hotels.find(h=>h.id===btn.dataset.hotel);const ev=h.evidence.find(x=>x.id===id);if(ev?.image)imageDelete(ev.image);h.evidence=h.evidence.filter(x=>x.id!==id);save();render();toast('资料已删除，推荐依据已更新');}}
  if(a==='view-image'){const ev=state.hotels.flatMap(h=>h.evidence).find(x=>x.id===id);const data=await imageGet(ev.image);if(data&&/^data:image\/(png|jpeg|webp);base64,/.test(data))showDialog('原始截图',`<img class="evidence-detail-image" src="${data}" alt="用户导入的原始评价截图"><p class="disclaimer">${E(ev.text)}</p>`);else toast('未找到截图，可尝试从备份导入');}
  if(a==='add-person'){if(state.people.length>=8){toast('第一版最多支持8位同行人');return;}const n=state.people.length+1;state.people.push({...structuredClone(demo().people[1]),id:uid(),name:'朋友'+n});save();render();toast('已添加同行人，请填写要求');}
  if(a==='preset'){let people=demo().people;if(id==='comfort')people=people.map(p=>({...p,budget:900,weights:{price:1,transit:2,newness:5,facilities:5}}));if(id==='tight')people=people.map(p=>({...p,budget:400,requireSmart:true}));state.people=people;save();render();toast('已应用偏好预设');}
  if(a==='reset'){switchMode('demo');if(state.mode!=='demo')return;state=demo();filterHotel='';filterPlatform='';save();render();toast('演示场景已恢复');}
  if(a==='method')showDialog('推荐怎么算？',`<p>先检查每个人的预算与必要条件。任何一项不满足就不列入推荐；必要设施未知或资料冲突时，标记待确认。</p><p>对满足条件的酒店，分别计算每人的偏好匹配分。先比较同行人中的最低分，再比较平均分；仍同分时按价格排序。最多推荐两家。</p><div class="help-box"><p>价格分：100 −（房价 ÷ 本人预算）× 45，限制在0—100。</p><p>交通分：100 − 地铁步行分钟 × 5，最低0。</p><p>新旧按每位同行人设置的年数区间判断。默认开业距入住年份不超过3年为较新，8年以上为年数较久；这不是行业标准。只有确认属于整间客房翻新且本人允许时，翻新年才参与判断。</p><p>设施分：仅计算本人选择的条件，来源明确符合记100、明确不符合记0、未知暂记25；没有选条件时不假定偏好。该分数仅是规则预览，最终AI还会阅读体验与取舍。</p><p>以上按各人0—5的重要程度加权。所有权重为0时记50分。</p></div><p class="disclaimer">这些是第一期可检查、可修改的演示规则，不是模型预测或酒店质量评分。</p>`);
});
document.addEventListener('submit',async e=>{
  if(e.target.id==='policy-form'){e.preventDefault();savePolicyForm(e.target);return;}
  if(e.target.id==='trip-form'){e.preventDefault();const f=new FormData(e.target);if(f.get('checkin')&&f.get('checkout')&&f.get('checkout')<=f.get('checkin')){toast('退房日期需要晚于入住日期');return;}const cityChanged=HotelJourney.city(state.trip.city)!==HotelJourney.city(f.get('city'));state.functionalTest=f.has('functionalTest');state.trip=Object.fromEntries(['city','checkin','checkout','area'].map(k=>[k,String(f.get(k)||'')]));if(cityChanged)delete state.hotelSelection;delete state.aiResult;save();render();toast('行程已保存');}
  if(e.target.id==='preferences-form'){e.preventDefault();const f=new FormData(e.target);state.people=state.people.map((p,i)=>({...p,name:String(f.get(i+'-name')).trim()||'同行人',budget:Number(f.get(i+'-budget')),maxMetro:Number(f.get(i+'-maxMetro')),...Object.fromEntries(['budgetHard','requireSmart','requireLaundry','avoidMold','transitHard'].map(k=>[k,f.has(i+'-'+k)])),weights:Object.fromEntries(['price','transit','newness','facilities'].map(k=>[k,Number(f.get(i+'-weight-'+k))]))}));state.preferencesConfirmed=true;save();go('compare');toast('偏好已保存，请重新生成 AI 推荐');}
  if(e.target.id==='hotel-form'){e.preventDefault();const form=e.target,f=new FormData(form),id=form.dataset.id;const old=state.hotels.find(h=>h.id===id);const num=k=>f.get(k)===''?null:Number(f.get(k)),tri=k=>f.get(k)===''?null:f.get(k)==='true';const makeReal=f.has('makeReal');const h={...old,id,city:String(f.get('city')).trim(),name:String(f.get('name')).trim(),area:f.get('area'),room:f.get('room'),price:num('price'),metro:num('metro'),terms:f.get('terms'),quoteDate:f.get('quoteDate'),source:f.get('source'),demo:state.mode==='demo',manualTripScope:!old||HotelJourney.belongs(old,state.trip,state.people)?HotelJourney.tripScope(state.trip,state.people):old.manualTripScope,facts:{...old?.facts,...(window.HotelPreferences?.readHotelFacts?.(form)||{}),opened:num('opened'),renovated:num('renovated'),smart:tri('smart'),laundry:tri('laundry'),mold:tri('mold')},evidence:makeReal?[]:(old?.evidence||[])};if(!h.name){toast('请填写酒店名称');return;}if(HotelJourney.city(h.city)!==HotelJourney.city(state.trip.city)){toast('酒店城市与当前行程不一致，请先切换行程城市');return;}if(old)state.hotels=state.hotels.map(x=>x.id===id?h:x);else state.hotels.push(h);if(HotelJourney.belongs(h,state.trip,state.people)&&Array.isArray(state.hotelSelection))state.hotelSelection=[...new Set([...state.hotelSelection,id])];save();closeDialog();render();toast(HotelJourney.belongs(h,state.trip,state.people)?'酒店资料已保存到本次行程，请重新生成 AI 推荐':'历史资料已保存；未自动加入本次行程');}
  if(e.target.id==='evidence-form'){e.preventDefault();if(ocrBusy){toast('文字识别还在进行，请稍后保存');return;}const form=e.target,f=new FormData(form),h=state.hotels.find(h=>h.id===f.get('hotel'));const text=String(f.get('text')).trim();if(!text){toast('请填写或识别评价文字');return;}if(state.mode==='trip'&&f.has('isDemo')){toast('演示评价不能保存到我的行程。请转到演示模式测试，或取消保存。');return;}const claims={};for(const k of ['smart','smartWash','laundry','mold']){const value=f.get(k);if(value==='true'||value==='false')claims[k]=value==='true';}if(f.get('opened'))claims.opened=Number(f.get('opened'));const ev={id:uid(),text,claims,platform:f.get('platform'),date:f.get('date'),room:f.get('room')||'未注明',source:f.get('source'),confirmed:true,demo:state.mode==='demo'||f.has('isDemo'),aiAnalysis:window.StayAI?.getExtraction?.()||null,image:null};if(pendingImage){try{await imagePut(ev.id,pendingImage);ev.image=ev.id;}catch{toast('截图保存失败，请导出备份或检查浏览器储存空间后重试');return;}}h.evidence.push(ev);save();closeDialog();filterHotel=h.id;filterPlatform='';go('evidence');toast('依据已保存，已重新检查设施与冲突');}
});
document.querySelector('.trip-wrap').open=!matchMedia('(max-width:760px)').matches;
save();render();
